import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate discount percent (0-100, can have decimals).
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) return true;
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the due date for an invoice based on terms.
 * @param {string} issueDate Date in YYYY-MM-DD format
 * @param {string} terms 'NET14', 'NET30', or 'EOM'
 * @returns {string} Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Get last day of the month
    const [year, month] = issueDate.split('-');
    const nextMonth = parseInt(month) + 1;
    const nextMonthYear = nextMonth > 12 ? parseInt(year) + 1 : year;
    const nextMonthNum = nextMonth > 12 ? 1 : nextMonth;
    const lastDayStr = `${String(nextMonthYear).padStart(4, '0')}-${String(nextMonthNum).padStart(2, '0')}-01`;
    return addDays(lastDayStr, -1);
  }
}

/**
 * Create a new invoice in draft status.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: unknown }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer exists
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate issue date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return fail('TERMS_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Get customer tier for default discount
  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate quantity
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount percent
    if (!isValidDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product and validate SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: explicit value (even if 0) wins over tier discount
    if (line.discountPercent !== undefined && line.discountPercent !== null) {
      enrichedLine.discountPercent = line.discountPercent;
    } else {
      enrichedLine.discountPercent = tierDiscount;
    }

    enrichedLines.push(enrichedLine);
  }

  const dueDate = calculateDueDate(issueDate, terms);

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

/**
 * Calculate the total of a single line item (qty * unitPrice, before discount).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount amount in cents
 */
export function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  return roundCents(lineTotal(line) * line.discountPercent / 100);
}

/**
 * Calculate the VAT for a single line item (on the amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT amount in cents
 */
export function lineVat(line) {
  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
  return roundCents(amountAfterDiscount * line.vatRate / 100);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
  const discount = roundCents(invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
  const vat = roundCents(invoice.lines.reduce((sum, line) => sum + lineVat(line), 0));
  const total = Math.max(0, roundCents(subtotal - discount + vat));

  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add a line to an invoice or increase qty if the SKU already exists.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: unknown, discountPercent?: unknown }} line
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate quantity
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discount percent
  if (!isValidDiscount(discountPercent)) return fail('DISCOUNT_INVALID');

  // Get product and validate SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Get customer tier for default discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier] ?? 0;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find existing line with same SKU
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    // Update existing line
    newLines[existingLineIndex].qty += qty;
    // Apply discount: explicit value (even if 0) wins over tier discount
    if (discountPercent !== undefined && discountPercent !== null) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    } else if (newLines[existingLineIndex].discountPercent === undefined) {
      newLines[existingLineIndex].discountPercent = tierDiscount;
    }
  } else {
    // Add new line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: explicit value (even if 0) wins over tier discount
    if (discountPercent !== undefined && discountPercent !== null) {
      newLine.discountPercent = discountPercent;
    } else {
      newLine.discountPercent = tierDiscount;
    }

    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find line to remove
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check that it's not the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new invoice without the line
  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice by assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers Array of invoice numbers already used
 * @returns {{ ok: true, value: { number: string, customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

