test('createInvoice succeeds with valid customer, date, and one line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(result.value.lines[0].name, 'Logo package');
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[0].unitPrice, 120000);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID to uppercase', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const result = createInvoice({
    customerId: ' C-001 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID mixed case and spaces', () => {
  const result = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice defaults to NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2025-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2025-10-21');
});

test('createInvoice calculates NET30 due date', () => {
  const tests = [
    { issue: '2025-01-15', expected: '2025-02-14' },
    { issue: '2025-01-01', expected: '2025-01-31' },
    { issue: '2025-12-01', expected: '2025-12-31' },
  ];

  for (const { issue, expected } of tests) {
    const result = createInvoice({
      customerId: 'C-002',
      issueDate: issue,
      lines: [{ sku: 'LOGO-PACK', qty: 1 }],
      terms: 'NET30',
    });

    assert.equal(result.ok, true, `Should succeed for ${issue}`);
    assert.equal(result.value.dueDate, expected, `NET30 due date should be correct for ${issue}`);
  }
});

test('createInvoice calculates EOM due date for various months', () => {
  const tests = [
    { issue: '2025-01-15', expected: '2025-01-31' }, // Jan has 31 days
    { issue: '2025-02-15', expected: '2025-02-28' }, // Feb 2025 has 28 days
    { issue: '2024-02-15', expected: '2024-02-29' }, // Feb 2024 (leap year) has 29 days
    { issue: '2025-04-15', expected: '2025-04-30' }, // Apr has 30 days
    { issue: '2025-12-01', expected: '2025-12-31' }, // Dec has 31 days
  ];

  for (const { issue, expected } of tests) {
    const result = createInvoice({
      customerId: 'C-002',
      issueDate: issue,
      lines: [{ sku: 'LOGO-PACK', qty: 1 }],
      terms: 'EOM',
    });

    assert.equal(result.ok, true, `Should succeed for ${issue}`);
    assert.equal(result.value.dueDate, expected, `EOM due date should be end of month for ${issue}`);
  }
});

test('createInvoice fails with invalid terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'INVALID',
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'TERMS_INVALID');
});

test('createInvoice stores terms on all status changes', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2025-10-21');
});

test('createInvoice succeeds with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'BRAND-BOOK', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(result.value.lines[1].sku, 'BRAND-BOOK');
  assert.equal(result.value.lines[1].name, 'Brand guidelines document');
  assert.equal(result.value.lines[1].qty, 2);
});

test('createInvoice fails with unknown customer', () => {
  const result = createInvoice({
    customerId: 'UNKNOWN',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice fails with invalid date format', () => {
  const tests = [
    '2025-10-7',
    '2025-1-07',
    '25-10-07',
    '10-07-2025',
    '2025/10/07',
    'invalid',
    '2025-13-01',
    '2025-02-30',
  ];

  for (const dateStr of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    });

    assert.equal(result.ok, false, `Should fail for date: ${dateStr}`);
    assert.equal(result.error, 'DATE_INVALID', `Should fail with DATE_INVALID for date: ${dateStr}`);
  }
});

test('createInvoice fails with empty lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice fails with non-array lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: null,
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NO_LINES');
});

test('createInvoice fails with invalid quantity', () => {
  const tests = [
    { qty: 0, desc: 'zero' },
    { qty: -1, desc: 'negative' },
    { qty: 1.5, desc: 'non-integer' },
    { qty: '2', desc: 'string' },
    { qty: null, desc: 'null' },
  ];

  for (const { qty, desc } of tests) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-07',
      lines: [{ sku: 'LOGO-PACK', qty }],
    });

    assert.equal(result.ok, false, `Should fail for ${desc}`);
    assert.equal(result.error, 'QTY_INVALID', `Should fail with QTY_INVALID for ${desc}`);
  }
});

test('createInvoice fails with unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'UNKNOWN_SKU', qty: 1 }],
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  };
  const original = JSON.stringify(input);

  createInvoice(input);

  assert.equal(JSON.stringify(input), original);
});

test('lineTotal calculates qty * unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 120000 }), 240000);
  assert.equal(lineTotal({ qty: 5, unitPrice: 50 }), 250);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
});

test('lineTotal returns integer cents', () => {
  const result = lineTotal({ qty: 3, unitPrice: 6000 });
  assert.equal(Number.isInteger(result), true);
  assert.equal(result, 18000);
});

test('invoiceTotals calculates subtotal from all lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
      { qty: 2, unitPrice: 245000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 610000);
  // VAT: 21% of 610000 = 128100
  assert.equal(totals.vat, 128100);
  assert.equal(totals.total, 738100);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25500);
  // VAT: 21% of 25500 = 5355
  assert.equal(totals.vat, 5355);
  assert.equal(totals.total, 30855);
});

test('invoiceTotals with multiple lines of varying prices', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
      { qty: 2, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 4, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000 + 19000 + 148);
  // Line 1 VAT: 21% of 120000 = 25200
  // Line 2 VAT: 21% of 19000 = 3990
  // Line 3 VAT: 9% of 148 = 13
  // Total VAT: 29203
  assert.equal(totals.vat, 29203);
  assert.equal(totals.total, 168351);
});

test('invoiceTotals with invoices created from createInvoice', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
