  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // LOGO-PACK: 120000 cents, 5% discount = 6000
  // Amount after discount: 114000, VAT 21% = 23940
  // total = 120000 - 6000 + 23940 = 137940
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 6000);
  assert.equal(totals.vat, 23940);
  assert.equal(totals.total, 137940);
});

test('lineVat calculates VAT on amount after discount', () => {
  const line = { qty: 1, unitPrice: 100000, discountPercent: 10, vatRate: 21 };
  const vat = lineVat(line);
  // 100000 - (10% of 100000) = 90000
  // 21% of 90000 = 18900
  assert.equal(vat, 18900);
});

test('lineVat with no discount', () => {
  const line = { qty: 1, unitPrice: 100000, vatRate: 21 };
  const vat = lineVat(line);
  // 21% of 100000 = 21000
  assert.equal(vat, 21000);
});

