  const vat = lineVat(line);
  assert.equal(vat, 0);
});

test('lineVat with 9% VAT rate', () => {
  const line = { qty: 2, unitPrice: 25000, vatRate: 9 };
  const vat = lineVat(line);
  // 2 * 25000 = 50000
  // 9% of 50000 = 4500
  assert.equal(vat, 4500);
});

