  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // LOGO-PACK: 120000 cents, vatRate 21%
  // No discount, so VAT = 21% of 120000 = 25200
  // total = 120000 - 0 + 25200 = 145200
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals with discount and VAT', () => {
  // C-002 is standard tier (no discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // LOGO-PACK: 120000 cents, 10% discount = 12000
  // Amount after discount: 108000
  // VAT 21% of 108000 = 22680
  // total = 120000 - 12000 + 22680 = 130680
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 12000);
  assert.equal(totals.vat, 22680);
  assert.equal(totals.total, 130680);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  // C-002 is standard tier (no discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },  // 120000, vatRate 21
      { sku: 'PRINT-A4', qty: 100 }, // 37 * 100 = 3700, vatRate 9
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // Line 1: 120000, VAT 21% = 25200
  // Line 2: 3700, VAT 9% = 333
  // total VAT = 25533
  // total = 123700 - 0 + 25533 = 149233
  assert.equal(totals.subtotal, 123700);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25533);
  assert.equal(totals.total, 149233);
});

test('invoiceTotals with tier discount and VAT', () => {
  // C-008 is gold tier (5% discount)
  const result = createInvoice({
    customerId: 'C-008',
    issueDate: '2025-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  // LOGO-PACK: 120000, 5% discount = 6000
  // Amount after discount: 114000
  // VAT 21% of 114000 = 23940
  // total = 120000 - 6000 + 23940 = 137940
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 6000);
  assert.equal(totals.vat, 23940);
  assert.equal(totals.total, 137940);
});

test('invoiceTotals clamps total at 0 even with VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100000, discountPercent: 100, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);

  // 100% discount cancels out the line, VAT is 0
  // total should be 0, not negative
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 100000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

